package com.github.yourname.rotp_bnrwk.init;

import com.github.yourname.rotp_bnrwk.BnrwkAddon;

import net.minecraft.util.ResourceLocation;
import net.minecraft.util.SoundEvent;
import net.minecraftforge.fml.RegistryObject;
import net.minecraftforge.registries.DeferredRegister;
import net.minecraftforge.registries.ForgeRegistries;

/** Sound events. Files live in assets/rotp_bnrwk/sounds (generated by tools/gen_sounds.py), mapping in sounds.json. */
public class InitSounds {
    public static final DeferredRegister<SoundEvent> SOUNDS = DeferredRegister.create(
            ForgeRegistries.SOUND_EVENTS, BnrwkAddon.MOD_ID);

    public static final RegistryObject<SoundEvent> SUMMON = sound("summon");
    public static final RegistryObject<SoundEvent> BARRAGE = sound("barrage");
    public static final RegistryObject<SoundEvent> PLANT = sound("plant");
    public static final RegistryObject<SoundEvent> THROW = sound("throw");
    public static final RegistryObject<SoundEvent> SMOKE = sound("smoke");
    public static final RegistryObject<SoundEvent> TICK = sound("tick");
    public static final RegistryObject<SoundEvent> TOCK = sound("tock");
    public static final RegistryObject<SoundEvent> PIN_SPRING = sound("pin_spring");
    public static final RegistryObject<SoundEvent> BOMB_EXPLODE = sound("bomb_explode");

    private static RegistryObject<SoundEvent> sound(String name) {
        return SOUNDS.register(name, () -> new SoundEvent(new ResourceLocation(BnrwkAddon.MOD_ID, name)));
    }
}
